import{_ as o,a0 as u,w as a,s as p,ao as s,I as l,x as e,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"BLUI：创建游戏 UI 的简单方法 | LCTT x X-CMD","titleTemplate":false,"description":"BLUI：创建游戏 UI 的简单方法 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"BLUI：创建游戏 UI 的简单方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"BLUI：创建游戏 UI 的简单方法 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180615 BLUI- An easy way to create game UI","title":"BLUI：创建游戏 UI 的简单方法","tag":"201807","desc":""},"relativePath":"201807/20180615 BLUI- An easy way to create game UI.md","filePath":"[post].md"}'),m={name:"201807/20180615 BLUI- An easy way to create game UI.md"};function I(d,t,U,g,L,b){const n=u("Link");return a(),p("div",null,[t[28]||(t[28]=s('<h1 id="blui-创建游戏-ui-的简单方法" tabindex="-1">BLUI：创建游戏 UI 的简单方法 <a class="header-anchor" href="#blui-创建游戏-ui-的简单方法" aria-label="Permalink to “BLUI：创建游戏 UI 的简单方法”">​</a></h1><blockquote><p>开源游戏开发插件运行虚幻引擎的用户使用基于 Web 的编程方式创建独特的用户界面元素。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/gaming_plugin_blui_screenshot.jpg?itok=91nnYCt_" alt=""></p><p>游戏开发引擎在过去几年中变得越来越易于​​使用。像 Unity 这样一直免费使用的引擎，以及最近从基于订阅的服务切换到免费服务的<ruby>虚幻引擎<rt>Unreal Engine</rt></ruby>，允许独立开发者使用 AAA 发行商相同达到行业标准的工具。虽然这些引擎都不是开源的，但每个引擎都能够促进其周围的开源生态系统的发展。</p><p>这些引擎中可以包含插件以允许开发人员通过添加特定程序来增强引擎的基本功能。这些程序的范围可以从简单的资源包到更复杂的事物，如人工智能 （AI） 集成。这些插件来自不同的创作者。有些是由引擎开发工作室和有些是个人提供的。后者中的很多是开源插件。</p><h3 id="什么是-blui" tabindex="-1">什么是 BLUI？ <a class="header-anchor" href="#什么是-blui" aria-label="Permalink to “什么是 BLUI？”">​</a></h3>',6)),l("p",null,[t[1]||(t[1]=e("作为独立游戏开发工作室的一员，我体验到了在专有游戏引擎上使用开源插件的好处。Aaron Shea 开发的一个开源插件 ",-1)),i(n,{href:"https://github.com/AaronShea/BLUI"},{default:r(()=>[...t[0]||(t[0]=[e("BLUI",-1)])]),_:1}),t[2]||(t[2]=e(" 对我们团队的开发过程起到了重要作用。它允许我们使用基于 Web 的编程（如 HTML/CSS 和 JavaScript）创建用户界面 （UI） 组件。尽管",-1)),t[3]||(t[3]=l("ruby",null,[e("虚幻引擎"),l("rt",null,"Unreal Engine")],-1)),t[4]||(t[4]=e("（我们选择的引擎）有一个实现了类似目的的内置 UI 编辑器，我们也选择使用这个开源插件。我们选择使用开源替代品有三个主要原因：它们的可访问性、易于实现以及伴随的开源程序活跃的、支持性好的在线社区。",-1))]),t[29]||(t[29]=l("p",null,"在虚幻引擎的最早版本中，我们在游戏中创建 UI 的唯一方法是通过引擎的原生 UI 集成，使用 Autodesk 的 Scaleform 程序，或通过在虚幻社区中传播的一些选定的基于订阅的虚幻引擎集成。在这些情况下，这些解决方案要么不能为独立开发者提供有竞争力的 UI 解决方案，对于小型团队来说太昂贵，要么只能为大型团队和 AAA 开发者提供。",-1)),l("p",null,[t[6]||(t[6]=e("在商业产品和虚幻引擎的原生整合失败后，我们向独立社区寻求解决方案。我们在那里发现了 BLUI。它不仅与虚幻引擎无缝集成，而且还保持了一个强大且活跃的社区，经常推出更新并确保独立开发人员可以轻松访问文档。BLUI 使开发人员能够将 HTML 文件导入虚幻引擎，并在程序内部对其进行编程。这使得通过 web 语言创建的 UI 能够集成到游戏的代码、资源和其他元素中，并拥有所有 HTML、CSS、Javascript 和其他网络语言的能力。它还为开源 ",-1)),i(n,{href:"https://bitbucket.org/chromiumembedded/cef"},{default:r(()=>[...t[5]||(t[5]=[e("Chromium Embedded Framework",-1)])]),_:1}),t[7]||(t[7]=e(" 提供全面支持。",-1))]),t[30]||(t[30]=s('<h3 id="安装和使用-blui" tabindex="-1">安装和使用 BLUI <a class="header-anchor" href="#安装和使用-blui" aria-label="Permalink to “安装和使用 BLUI”">​</a></h3><p>使用 BLUI 的基本过程包括首先通过 HTML 创建 UI。开发人员可以使用任何工具来实现此目的，包括<ruby>自举<rt>bootstrapped</rt></ruby> JavaScript 代码、外部 API 或任何数据库代码。一旦这个 HTML 页面完成，你可以像安装任何虚幻引擎插件那样安装它，并加载或创建一个项目。项目加载后，你可以将 BLUI 函数放在虚幻引擎 UI 图纸中的任何位置，或者通过 C++ 进行硬编码。开发人员可以通过其 HTML 页面调用函数，或使用 BLUI 的内部函数轻松更改变量。</p><p><img src="https://opensource.com/sites/default/files/uploads/blui_gaming_plugin-integratingblui.png" alt="Integrating BLUI into Unreal Engine 4 blueprints" title="Integrating BLUI into Unreal Engine 4 blueprints"></p><p><em>将 BLUI 集成到虚幻 4 图纸中。</em></p><p>在我们当前的项目中，我们使用 BLUI 将 UI 元素与游戏中的音轨同步，为游戏机制的节奏方面提供视觉反馈。将定制引擎编程与 BLUI 插件集成很容易。</p><p><img src="https://opensource.com/sites/default/files/uploads/blui_gaming_plugin-syncui.png" alt="Using BLUI to sync UI elements with the soundtrack." title="Using BLUI to sync UI elements with the soundtrack."></p><p><em>使用 BLUI 将 UI 元素与音轨同步。</em></p>',7)),l("p",null,[t[10]||(t[10]=e("通过 BLUI GitHub 页面上的",-1)),i(n,{href:"https://github.com/AaronShea/BLUI/wiki"},{default:r(()=>[...t[8]||(t[8]=[e("文档",-1)])]),_:1}),t[11]||(t[11]=e("，将 BLUI 集成到虚幻 4 中是一个轻松的过程。还有一个由支持虚幻引擎开发人员组成的",-1)),i(n,{href:"https://forums.unrealengine.com/community/released-projects/29036-blui-open-source-html5-js-css-hud-ui"},{default:r(()=>[...t[9]||(t[9]=[e("论坛",-1)])]),_:1}),t[12]||(t[12]=e("，他们乐于询问和回答关于插件以及实现该工具时出现的任何问题。",-1))]),t[31]||(t[31]=l("h3",{id:"开源优势",tabindex:"-1"},[e("开源优势 "),l("a",{class:"header-anchor",href:"#开源优势","aria-label":"Permalink to “开源优势”"},"​")],-1)),t[32]||(t[32]=l("p",null,"开源插件可以在专有游戏引擎的范围内扩展创意。他们继续降低进入游戏开发的障碍，并且可以产生前所未有的游戏内的机制和资源。随着对专有游戏开发引擎的访问持续增长，开源插件社区将变得更加重要。不断增长的创造力必将超过专有软件，开源代码将会填补这些空白，并促进开发真正独特的游戏。而这种新颖性正是让独立游戏如此美好的原因！",-1)),t[33]||(t[33]=l("hr",null,null,-1)),l("p",null,[t[14]||(t[14]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/18/6/blui-game-development-plugin"},{default:r(()=>[...t[13]||(t[13]=[e("https://opensource.com/article/18/6/blui-game-development-plugin",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/uwikaiddi"},{default:r(()=>[...t[15]||(t[15]=[e("Uwana lkaiddi",-1)])]),_:1}),t[20]||(t[20]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[16]||(t[16]=[e("lujun9972",-1)])]),_:1}),t[21]||(t[21]=e(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:r(()=>[...t[17]||(t[17]=[e("geekpi",-1)])]),_:1}),t[22]||(t[22]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[18]||(t[18]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[25]||(t[25]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[23]||(t[23]=[e("LCTT",-1)])]),_:1}),t[26]||(t[26]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:r(()=>[...t[24]||(t[24]=[e("Linux中国",-1)])]),_:1}),t[27]||(t[27]=e(" 荣誉推出",-1))])])}const A=o(m,[["render",I]]);export{T as __pageData,A as default};
